WITH filtered AS (SELECT *, CONCAT_WS('/', status, account_type) AS status_account_type_key FROM accounts WHERE opened_date > DATE '2023-07-07' AND status IS NOT NULL AND customer_id = 12) SELECT id, customer_id, account_type, balance, opened_date, status, status_account_type_key, ROW_NUMBER() OVER w_recent AS seq_no, SUM(balance) OVER w_recent_2 AS customer_id_sum_balance, LAG(balance, 1) OVER (PARTITION BY customer_id ORDER BY opened_date, id) AS prev_balance FROM filtered WINDOW w_recent AS (PARTITION BY account_type, status ORDER BY opened_date DESC, id), w_recent_2 AS (PARTITION BY customer_id, account_type)
